mapper.select:
SELECT g.id, g.school_id, s.school_name AS school_name, g.grade_name AS name, g.grade_code AS code, NULL AS enroll_year, g.sort AS grade_num, g.status, g.sort, '' AS remark, g.create_time, (SELECT COUNT(1) FROM class_info c WHERE c.grade_id = g.id AND c.deleted = 0) AS class_count, (SELECT COUNT(1) FROM student st JOIN class_info c ON st.class_id = c.id WHERE c.grade_id = g.id AND st.deleted = 0 AND c.deleted = 0) AS student_count FROM grade g LEFT JOIN school s ON g.school_id = s.id WHERE g.deleted = 0
AND g.school_id = #{query.schoolId}
AND g.grade_name LIKE CONCAT('%', #{query.name}, '%')
AND g.status = #{query.status}
ORDER BY g.sort ASC, g.create_time DESC

SELECT id, school_id, grade_name AS name, grade_code AS code, NULL AS enroll_year, sort AS grade_num, sort, '' AS remark FROM grade WHERE school_id = #{schoolId} AND deleted = 0
AND status = #{status}
ORDER BY sort ASC, create_time DESC
